const R = $json.valueRanges || [];
const pick = (n) => (R.find(x => String(x.range||'').indexOf(n) === 0) || {}).values || [];
const crit = pick('INVESTOR_CRITERIA');
const inv  = pick('INVESTORS!');
const g = (row,i) => (row && row[i] != null) ? String(row[i]).trim() : '';

const TARGET = 272;
const NEW = 'Verge HealthTech Fund';

// Guard 1: INVESTORS row 272 must currently be a Verge row and not already renamed
const ir = inv[TARGET-1];
if (!ir) throw new Error('no INVESTORS row ' + TARGET);
const oldInv = g(ir,0);
if (!/verge/i.test(oldInv)) throw new Error('INVESTORS row ' + TARGET + ' is not a Verge row, it is "' + oldInv + '" - refusing');
if (oldInv === NEW) throw new Error('INVESTORS row ' + TARGET + ' already reads "' + NEW + '" - nothing to do');

// Guard 2: resolve the criteria row by scanning column A (never by physical position)
let critPhys = null;
for (let i = 1; i < crit.length; i++) { if (g(crit[i],0) === String(TARGET)) { critPhys = i + 1; break; } }
if (!critPhys) throw new Error('no INVESTOR_CRITERIA row with sheet_row ' + TARGET);
const oldCrit = g(crit[critPhys-1],1);
if (!/verge/i.test(oldCrit)) throw new Error('criteria physical row ' + critPhys + ' is "' + oldCrit + '", not a Verge row - refusing');

// Guard 3: confirm the contact is Miguel Legarda, which is how we disambiguated the firm
const contact = g(ir,1);
if (!/legarda/i.test(contact)) throw new Error('contact on row ' + TARGET + ' is "' + contact + '", expected Miguel Legarda - refusing in case the row moved');

const data = [
  { range: 'INVESTORS!A' + TARGET, values: [[NEW]] },
  { range: 'INVESTOR_CRITERIA!B' + critPhys, values: [[NEW]] }
];

return [{ json: { body: { valueInputOption: 'RAW', data: data },
  investors_row: TARGET, criteria_physical_row: critPhys,
  old_investors_name: oldInv, old_criteria_name: oldCrit, new_name: NEW, contact: contact, cells: data.length } }];
